/*
 * Symbolic Slothy source for NTRU+768 Phase 4 8-way parallel 32-point NTT,
 * rowpack-output v2 experiment.
 *
 * This is not production assembly and must not replace my_32ntt.opt.s until a
 * generated candidate passes the Forward NTT rowpack-output contract and full
 * pipeline validation.
 *
 * Forward kernel contract:
 *
 *   natural input -> complete bit-reversed output in GT rowpack SoA layout
 *   input comes only from my_ntt.s Phase123 row buffers
 *   radix-2 Cooley-Tukey butterfly:
 *     t  = fqmul(high, twiddle)
 *     lo = low + t
 *     hi = low - t
 *
 * Arithmetic is intentionally the same as ntt32_symbolic.s through stage 5.
 * The only semantic change is the final output layout.  Instead of storing
 * each output vector as low/high D halves to block-major GT layout,
 * each stage345 block transposes eight Q vectors and stores rowpack
 * planes:
 *
 *   rowpack_index(branch,row,lane,k32) = branch*384 + row*128 + lane*32 + k32
 *
 * At function entry for one Good-Thomas row, scatter_ptr = x10 points to
 * dst + 256*row.  For one stage345 block b, k32 = 8*b + [0..7].  The rowpack
 * stores are:
 *
 *   branch0 lane l -> [scatter_ptr + 64*l + 16*b]
 *   branch1 lane l -> [scatter_ptr + 768 + 64*l + 16*b]
 *
 * This source intentionally does not reduce the 32 loaded input vectors.
 * Phase123 feeds raw 3-point DFT outputs bounded by 3*(q-1).  The five lazy
 * CT stages stay below signed int16 range.  By default the final stage345
 * stores reduce to canonical range before the 8x8 transpose and rowpack Q
 * stores.  Defining NTT32_ROWPACK_V2_LAZY_OUTPUT=1 skips only that final
 * canonical reduction and makes downstream rowpack arithmetic responsible for
 * accepting lazy representatives modulo q.  Do not use this kernel as a
 * standalone arbitrary-int16 NTT32 without restoring input normalization,
 * final output normalization, or tightening the caller contract.
 *
 * Layout consumed by this file:
 *
 *   Q0  = [row_base + 16*0]
 *   Q1  = [row_base + 16*1]
 *   ...
 *   Q31 = [row_base + 16*31]
 *
 * Each Q vector contains 8 independent lanes.  The work index is carried by
 * the Q register number, so a CT butterfly is a vector operation between
 * work[i] and work[j].
 *
 * Region cut for practical Slothy RA:
 *
 *   1. stage12_stripe0..7 each load four work vectors, compute stage 1 and
 *      stage 2 for one stripe, then store the stage-2 values back to row_base.
 *   2. stage345_block0..3 each load one 8-vector block of stage-2 values,
 *      finish stage 3/4/5 inside that block, reduce, transpose 8x8 halfword
 *      lanes, and store rowpack planes.
 *
 * Every Slothy label boundary is also a memory boundary.  This avoids carrying
 * 32 symbolic work vectors across regions and lets each region be allocated
 * independently.
 *
 * Register contract for these symbolic regions:
 *   dst           = x0 points at the final poly_ntt output; kept for ABI
 *                   compatibility with the existing _ntt32_8way caller.
 *   row_base      = x4 points at the 32-Q staged input/output block.
 *   scatter_ptr   = x10 points at rowpack dst + 256*row for the current
 *                   Good-Thomas row.
 *   scatter_hi    = x11 is a concrete GPR temporary for branch1 row base.
 *   tw_ptr        = x12 is reset before each region that loads twiddle vectors.
 *   v0.h[0]       = q = 3457 and must be reserved in Slothy config.
 *   v0.h[1]       = Barrett reduce constant used by final output reduction.
 */

dst           .req x0
row_base      .req x4
tw_ptr        .req x12
scatter_ptr   .req x10
scatter_hi    .req x11

.ifndef NTT32_ROWPACK_V2_LAZY_OUTPUT
    .equ NTT32_ROWPACK_V2_LAZY_OUTPUT, 0
.endif

/*
 * Stage 1/2 stripes.  Stripe s touches work[s], work[s+8], work[s+16],
 * and work[s+24].  The store at the end is the handoff to stage345 blocks.
 */

    .global ntt32_8way
    .global _ntt32_8way
ntt32_8way:
_ntt32_8way:
